public.icash_owner_batch_candidates(uuid.definition:
CREATE OR REPLACE FUNCTION public.icash_owner_batch_candidates(p_account uuid, p_screening uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;r public.icash_operation_rates;n integer;result jsonb;pinned jsonb;
begin
 select * into c from public.icash_discovery_configs where account_id=p_account;
 select * into r from public.icash_operation_rates where id=c.contact_rate_id;
 if coalesce(c.research_version,0) not in (1,2) or not c.enabled or not c.contacts_enabled or c.data_rights_until<=now() or not r.enabled or r.operation<>'owner_enrichment' or r.expires_at<=now() then return '[]';end if;
 n:=least(5,greatest(0,floor((least(public.icash_prospecting_available(p_account),coalesce((select balance_cents-reserved_cents from public.icash_wallets where account_id=p_account),0))-public.icash_prospecting_outreach_floor(p_account))::numeric/greatest(1,r.charge_cents))::integer));
 pinned:=icash_research_private.owner_preflight_cohort(p_account,p_screening);
 if pinned is not null and jsonb_array_length(pinned)>n then return '[]';end if;
 select coalesce(jsonb_agg(jsonb_build_object('screeningId',id,'snapshot',snapshot) order by (id=p_screening) desc,id),'[]') into result from (
  select s.id,s.snapshot from public.icash_screening_jobs s where s.account_id=p_account
  and (pinned is null or exists(select 1 from jsonb_array_elements(pinned) i where i->>'screeningId'=s.id::text and i->'snapshot'=s.snapshot))
  and not public.icash_owner_preflight_sibling_waiting(s.account_id,s.id,s.snapshot,p_screening) and not public.icash_owner_preflight_empty(s.account_id,s.id,s.snapshot) and s.state='complete' and s.completed_at between now()-interval '24 hours' and now()
  and s.result->'financialCheck'->>'status'='eligible' and not s.snapshot ? 'sellerRequest' and s.snapshot->>'propertyType'='house'
  and public.icash_research_state_allowed(s.snapshot->'raw'->'data'->>'state')
  and not exists(select 1 from public.icash_property_controls pc where pc.account_id=p_account and pc.property_id=s.snapshot->>'propertyId' and pc.manual)
  and not exists(select 1 from public.icash_owner_contacts oc join public.icash_screening_jobs prior on prior.id=oc.screening_id where oc.account_id=p_account and prior.snapshot->>'propertyId'=s.snapshot->>'propertyId' and oc.created_at>now()-interval '30 days')
  and not exists(select 1 from public.icash_operation_spend o join public.icash_screening_jobs prior on o.operation_key='owners:'||p_account||':'||prior.id where prior.account_id=p_account and prior.snapshot->>'propertyId'=s.snapshot->>'propertyId' and o.state in ('reserved','dispatched'))
  and not exists(select 1 from public.icash_operation_spend o where o.operation_key='owners:'||p_account||':'||s.id)
  and (s.id=p_screening or not exists(select 1 from public.icash_automation_tickets t where t.screening_id=s.id))
  order by (s.id=p_screening) desc,s.id limit n
 ) q;
 if pinned is not null and jsonb_array_length(result)<>jsonb_array_length(pinned) then return '[]';end if;
 if not exists(select 1 from jsonb_array_elements(result) v where v->>'screeningId'=p_screening::text) then return '[]';end if;return result;
end $function$

public.icash_claim_owner_preflight(uuid,.definition:
CREATE OR REPLACE FUNCTION public.icash_claim_owner_preflight(p_account uuid, p_items jsonb, p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p icash_research_private.owner_export_preflights;item jsonb;ids jsonb;finger text;new_id uuid:=gen_random_uuid();parent_id uuid;next_generation integer:=1;cached boolean;renew boolean:=false;
begin
 if not exists(select 1 from icash_research_private.owner_export_settings where id=1 and preflight_enabled) then return '{"status":"disabled"}';end if;
 if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 5
  or octet_length(p_items::text)>524288 or jsonb_typeof(p_request->'people_ids') is distinct from 'array' then return '{"status":"held"}';end if;
 select jsonb_agg(to_jsonb(id) order by position) into ids from(
  select v#>>'{}' id,min(i.ordinality*1000+x.ordinality) position from jsonb_array_elements(p_items) with ordinality i(item,ordinality),jsonb_array_elements(i.item->'ids') with ordinality x(v,ordinality) group by v
 ) q;
 if ids is distinct from p_request->'people_ids' or jsonb_array_length(ids) not between 1 and 125
  or exists(select 1 from jsonb_array_elements_text(ids) id where id !~ '^per_[1-9][0-9]{0,15}$' or substring(id from 5)::numeric>9007199254740991)
  or (p_request @> '{"property_match":"owner","anchor":"person","require_phone":true,"scrub_dnc":true,"active_phones_only":true}') is distinct from true then return '{"status":"held"}';end if;
 if not pg_try_advisory_xact_lock(hashtextextended('owner-preflight:'||p_account,0)) then return '{"status":"pending"}';end if;
 if not exists(select 1 from public.icash_accounts where id=p_account and not bot_paused)
  or not public.icash_membership_work_allowed(p_account) or not public.icash_owner_export_people_available(ids) then return '{"status":"held"}';end if;
 for item in select value from jsonb_array_elements(p_items) loop
  if not exists(select 1 from public.icash_screening_jobs s where s.id=(item->>'screeningId')::uuid and s.account_id=p_account and s.state='complete' and s.snapshot=item->'snapshot')
   or not public.icash_owner_enrichment_unstarted(p_account,(item->>'screeningId')::uuid,'owners:'||p_account||':'||(item->>'screeningId')) then return '{"status":"held"}';end if;
 end loop;
 finger:=md5(jsonb_build_array(p_items,p_request)::text);
 select * into p from icash_research_private.owner_export_preflights where account_id=p_account and fingerprint=finger order by generation desc limit 1 for update;
 cached:=found;
 if cached and icash_research_private.owner_preflight_renewable(p.id) then parent_id:=p.id;next_generation:=p.generation+1;renew:=true;end if;
 if cached and not renew then
  if p.items is distinct from p_items or p.request is distinct from p_request then return '{"status":"held"}';end if;
  if p.state in ('ready','empty') then return jsonb_build_object('status',case when p.checked_at>clock_timestamp()-interval '30 minutes' or p.state='empty' then p.state else 'held' end);end if;
  if p.state='held' or p.created_at<clock_timestamp()-interval '30 minutes' or (p.state='waiting' and p.cleanup_attempts>0) then return '{"status":"held"}';end if;
  if p.state<>'waiting' or p.next_check_at>clock_timestamp() or not public.icash_dealmachine_capacity_available(3) then
   return jsonb_build_object('status',case when p.state in ('creating','checking') and p.started_at<clock_timestamp()-interval '90 seconds' then 'held' else 'pending' end);
  end if;
  update icash_research_private.owner_export_preflights set state='checking',lease=gen_random_uuid(),started_at=clock_timestamp() where id=p.id returning * into p;
 else
  perform 1 from public.icash_operating_budget where id=1 for update;
  if not found then return '{"status":"held"}';end if;
  if renew then
   -- Pause and source changes that won the shared budget lock also win renewal.
   perform 1 from public.icash_accounts where id=p_account and not bot_paused for update;
   if not found or not public.icash_membership_work_allowed(p_account) or not public.icash_owner_export_people_available(ids)
    or p.items is distinct from p_items or p.request is distinct from p_request
    or not exists(select 1 from public.icash_discovery_configs c join public.icash_operation_rates r on r.id=c.contact_rate_id
     where c.account_id=p_account and c.enabled and c.contacts_enabled and c.data_rights_until>now()
      and r.enabled and r.operation='owner_enrichment' and r.expires_at>now())
    or not exists(select 1 from public.icash_wallets where account_id=p_account and balance_cents>reserved_cents)
    then return '{"status":"held"}';end if;
   for item in select value from jsonb_array_elements(p_items) loop
    if not exists(select 1 from public.icash_screening_jobs s where s.id=(item->>'screeningId')::uuid and s.account_id=p_account
      and s.state='complete' and s.snapshot=item->'snapshot' and s.completed_at between now()-interval '24 hours' and now()
      and s.result->'financialCheck'->>'status'='eligible' and not s.snapshot ? 'sellerRequest'
      and s.snapshot->>'propertyType'='house' and public.icash_research_state_allowed(s.snapshot->'raw'->'data'->>'state'))
     or not public.icash_owner_enrichment_unstarted(p_account,(item->>'screeningId')::uuid,'owners:'||p_account||':'||(item->>'screeningId'))
     or coalesce(p_request->'mobile_only','false'::jsonb) is distinct from to_jsonb(public.icash_owner_targeting_pool(p_account,(item->>'screeningId')::uuid)='mobile')
     or exists(select 1 from public.icash_property_controls where account_id=p_account and property_id=item->'snapshot'->>'propertyId' and manual)
     then return '{"status":"held"}';end if;
   end loop;
  end if;

  if exists(select 1 from jsonb_array_elements(p_items) i where i->>'screeningId'<>p_items->0->>'screeningId' and exists(select 1 from public.icash_automation_tickets t where t.screening_id=(i->>'screeningId')::uuid)) then return '{"status":"quota_wait"}';end if;
  if exists(select 1 from jsonb_array_elements(p_items) i where public.icash_owner_preflight_sibling_waiting(p_account,(i->>'screeningId')::uuid,i->'snapshot',(p_items->0->>'screeningId')::uuid)) then return '{"status":"quota_wait"}';end if;
  if icash_research_private.owner_preflight_cohort(p_account,(p_items->0->>'screeningId')::uuid) is not null and icash_research_private.owner_preflight_cohort(p_account,(p_items->0->>'screeningId')::uuid) is distinct from p_items then return '{"status":"pending"}';end if;
  if not public.icash_dealmachine_capacity_available(1) then return '{"status":"quota_wait"}';end if;
  insert into icash_research_private.owner_export_preflights(id,account_id,fingerprint,items,request,state,list_name,supersedes,generation)
   values(new_id,p_account,finger,p_items,p_request,'creating','icash-owner-preflight-'||new_id,parent_id,next_generation) returning * into p;
  insert into icash_research_private.owner_export_preflight_items select p.id,p_account,(i->>'screeningId')::uuid,md5((i->'snapshot')::text) from jsonb_array_elements(p_items) i;
 end if;
 return jsonb_build_object('status',case when p.state='creating' then 'create' else 'check' end,'id',p.id,'lease',p.lease,'listId',p.list_id,'name',p.list_name,'ids',ids,'mobileOnly',p.request->'mobile_only'='true'::jsonb);
end $function$

public.icash_admit_owner_active_export(u.definition:
CREATE OR REPLACE FUNCTION public.icash_admit_owner_active_export(p_account uuid, p_primary uuid, p_batch uuid, p_items jsonb, p_preview jsonb, p_config jsonb, p_request jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ids jsonb;expected jsonb;admission text;item jsonb;person text;preview jsonb;match jsonb;
begin
 if not public.icash_owner_active_export_enabled() then return 'held';end if;
 if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 5 then return 'held';end if;
 select jsonb_agg(to_jsonb(id) order by position) into ids from (
  select v#>>'{}' as id,min(i.ordinality*1000+p.ordinality) as position
  from jsonb_array_elements(p_items) with ordinality i(item,ordinality),jsonb_array_elements(i.item->'ids') with ordinality p(v,ordinality) group by v
 ) u;
 if jsonb_array_length(ids) not between 1 and 125 or exists(select 1 from jsonb_array_elements_text(ids) id where id !~ '^per_[0-9]{1,100}$') then return 'held';end if;
 expected:=jsonb_build_object('people_ids',ids,'fields','["person_full_name","has_active_phone_number"]'::jsonb,'property_match','owner','anchor','person','limit',jsonb_array_length(ids),'require_phone',true,'scrub_dnc',true,'active_phones_only',true);

 if public.icash_owner_targeting_pool(p_account,p_primary)='mobile' then
  if not exists(select 1 from icash_research_private.targeting_settings where id=1 and mobile_verified) then return 'held';end if;
  expected:=expected||'{"mobile_only":true}'::jsonb;end if;
 if exists(select 1 from jsonb_array_elements(p_items) i where public.icash_owner_targeting_pool(p_account,(i->>'screeningId')::uuid)<>public.icash_owner_targeting_pool(p_account,p_primary)) then return 'held';end if;
 if p_request is distinct from expected then return 'held';end if;
 if exists(select 1 from icash_research_private.owner_export_settings where id=1 and preflight_enabled) and not exists(select 1 from icash_research_private.owner_export_preflights p where p.account_id=p_account and p.fingerprint=md5(jsonb_build_array(p_items,p_request)::text) and p.items=p_items and p.request=p_request and p.state='ready' and p.checked_at>clock_timestamp()-interval '30 minutes') then return 'held';end if;
 -- SQL repeats owner/phone availability proof before any quota or wallet claim.
 for item in select value from jsonb_array_elements(p_items) loop
  select value into strict preview from jsonb_array_elements(p_preview->'data') where value->>'dm_property_id'=item->'snapshot'->>'propertyId' and value->'found'='true'::jsonb;
  if (select count(distinct value) from jsonb_array_elements(item->'ids'))<>jsonb_array_length(item->'ids') then return 'held';end if;
  for person in select value from jsonb_array_elements_text(item->'ids') loop
   select value into match from jsonb_array_elements(preview->'contacts') where value->>'dm_person_id'=person limit 1;
   if not found or (match->>'contact_type' is not null and match->>'contact_type'<>'owner')
    or match->'is_likely_renter'='true'::jsonb
    or (match->'is_likely_owner'='true'::jsonb or (match->>'is_likely_owner' is null and match->>'contact_type'='owner')) is distinct from true
    or match->'availability'->'phones'='0'::jsonb then return 'held';end if;
  end loop;
 end loop;
 if not pg_try_advisory_xact_lock(hashtextextended('dealmachine:organization:owner-export',0)) then return 'export_busy';end if;
 if exists(select 1 from icash_research_private.owner_exports where terminal_at is null and capacity_review_id is null) then return 'export_busy';end if;
 admission:=public.icash_admit_owner_batch(p_account,p_primary,p_batch,p_items,p_preview,p_config||'{"ownerContract":"owner-active-export-v1"}');
 if admission<>'claimed' then return admission;end if;
 insert into icash_research_private.owner_exports(id,request) values(p_batch,p_request);
 return 'claimed';
end $function$
